import { NextRequest, NextResponse } from "next/server"
import { readFile, stat } from "fs/promises"
import path from "path"
import { uploadsDir } from "@/lib/uploads"

// Must run on the Node runtime (needs `fs`) and must never be statically
// optimised — uploads change at runtime.
export const runtime = "nodejs"
export const dynamic = "force-dynamic"

const MIME: Record<string, string> = {
  ".gif": "image/gif",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".webp": "image/webp",
  ".avif": "image/avif",
  // Voice messages are stored alongside images.
  ".webm": "audio/webm",
  ".ogg": "audio/ogg",
  ".mp3": "audio/mpeg",
  ".m4a": "audio/mp4",
  ".wav": "audio/wav",
}

// GET /api/uploads/<file> — serves uploaded images from the persistent uploads dir.
export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ path: string[] }> }
) {
  const { path: segments } = await params
  if (!segments || segments.length === 0) {
    return new NextResponse("Not found", { status: 404 })
  }

  // Collapse to a bare filename so no traversal sequence can escape the dir.
  const name = path.basename(segments.join("/"))
  if (!name || name.startsWith(".") || name.includes("..")) {
    return new NextResponse("Not found", { status: 404 })
  }

  const dir = uploadsDir()
  const fullPath = path.join(dir, name)
  // Defence in depth: confirm the resolved path really is inside the dir.
  if (!path.resolve(fullPath).startsWith(path.resolve(dir) + path.sep)) {
    return new NextResponse("Not found", { status: 404 })
  }

  try {
    const info = await stat(fullPath)
    if (!info.isFile()) return new NextResponse("Not found", { status: 404 })

    const buf = await readFile(fullPath)
    const ext = path.extname(fullPath).toLowerCase()

    return new NextResponse(new Uint8Array(buf), {
      headers: {
        "Content-Type": MIME[ext] ?? "application/octet-stream",
        "Content-Length": String(buf.byteLength),
        // Filenames already carry a timestamp and URLs carry a ?v= cache
        // buster, so each URL maps to immutable bytes and can be cached hard.
        "Cache-Control": "public, max-age=31536000, immutable",
        // Never let an uploaded file be interpreted as something executable.
        "X-Content-Type-Options": "nosniff",
        "Content-Disposition": `inline; filename="${name}"`,
      },
    })
  } catch {
    return new NextResponse("Not found", { status: 404 })
  }
}
